/* Small C/Wasm ABI adapter. One isolated engine per worker or replay context. */
async function createCompactEngine(bytes,onStage=()=>{}){let source=bytes;if(!source){onStage('Downloading compiled engine');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('compact-engine.wasm?v=heartbeat1',{signal:controller.signal});if(!response.ok)throw Error('Compiled engine download failed: '+response.status);source=await response.arrayBuffer()}catch(e){throw Error(e.name==='AbortError'?'Engine download timed out after 15 seconds. Retry the experiment.':e.message)}finally{clearTimeout(timeout)}}onStage('Compiling WebAssembly module');const {instance}=await WebAssembly.instantiate(source,{env:{sin:Math.sin,cos:Math.cos}}),e=instance.exports;let current=null;
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function begin(genome,c,traffic){if(genome.length!==c.cols*c.rows||traffic.length>3600)throw Error('Simulation input exceeds engine limits');new Uint8Array(e.memory.buffer,e.tiles_ptr(),genome.length).set(genome);let input=new Float64Array(e.memory.buffer,e.schedule_ptr(),traffic.length*4);traffic.forEach((p,i)=>input.set([p.time,p.x,p.y,p.entry],i*4));if(!e.configure(c.cols,c.rows,c.duration,c.speed,traffic.length,hash(c.seed+':impacts')))throw Error('Invalid simulation configuration');current={lastTiles:Uint8Array.from(genome),tiles:new Uint8Array(e.memory.buffer,e.tiles_ptr(),genome.length),c,time:0,particles:[],collisions:0,exits:0,bins:[],sparks:[]};return snapshot(current,true)}
function snapshot(s,visual){s.time=e.time_value();s.collisions=e.collision_count();s.exits=e.exit_count();s.bins=Array.from(new Int32Array(e.memory.buffer,e.bins_ptr(),s.c.duration));if(visual){e.snapshot();let view=new Float64Array(e.memory.buffer,e.particles_ptr(),e.active_count()*7);s.particles=Array.from({length:e.active_count()},(_,i)=>({x:view[i*7],y:view[i*7+1],entry:view[i*7+2],exit:view[i*7+3],u:view[i*7+4],px:view[i*7+5],py:view[i*7+6]}));s.sparks=s.sparks.filter(a=>(a.life-=1/60)>0)}return s}
return{kind:'C / WebAssembly',createSim:begin,tick(s){if(s!==current)throw Error('Simulation context is no longer active');let before=s.collisions;e.step(1);snapshot(s,true);if(s.collisions>before){/* Impact marker at the changed tile, independent of drawing. */for(let i=0;i<s.tiles.length;i++)if(s.lastTiles&&s.lastTiles[i]!==s.tiles[i])s.sparks.push({x:i%s.c.cols+.5,y:Math.floor(i/s.c.cols)+.5,life:.35})}s.lastTiles=Uint8Array.from(s.tiles);return s},evaluate(genome,c,traffic,onProgress){let s=begin(genome,c,traffic);for(let i=0;i<c.duration*60;i+=120){e.step(Math.min(120,c.duration*60-i));if(onProgress)onProgress(e.time_value(),e.collision_count())}snapshot(s,false);s.tiles=Uint8Array.from(s.tiles);return s},async evaluateAsync(genome,c,traffic,onProgress){let s=begin(genome,c,traffic),lastYield=Date.now();for(let i=0;i<c.duration*60;i+=8){e.step(Math.min(8,c.duration*60-i));if(onProgress)onProgress(e.time_value(),e.collision_count());if(Date.now()-lastYield>=16){await new Promise(resolve=>setTimeout(resolve,0));lastYield=Date.now()}}snapshot(s,false);s.tiles=Uint8Array.from(s.tiles);return s},memoryBytes:e.memory.buffer.byteLength};}
